// Utility functions for demo data
export function getScenarioByKey(key: string): DemoScenario | null {
  return DEMO_SCENARIOS[key] || null;
}

export function getAllScenarios(): DemoScenario[] {
  return Object.values(DEMO_SCENARIOS);
}

export function getProtocolDistributionData(scenario: DemoScenario) {
  return Object.entries(scenario.protocolDistribution).map(([protocol, days]) => ({
    name: protocol,
    value: days,
    percentage: (days / 365) * 100, // Adjust based on scenario length
    color: PROTOCOL_COLORS[protocol] || '#6B7280'
  }));
}

export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(amount);
}

export function formatPercentage(value: number): string {
  return `${value.toFixed(2)}%`;
}